module GCSim
  class Copying < HeapState
    def initialize(size)
      super
      @half = size / 2
      @base = @top = 0
    end

    def free_list
      limit = @base + @half
      @top < limit ? [[@top, limit - @top]] : []
    end

    def inactive_range
      first = @half - @base
      [first, first + @half]
    end

    def fits?(obj) = @top + obj.size <= @base + @half

    def place(obj)
      obj.address = @top
      @top += obj.size
      @objects << obj
    end

    def allocate(obj, roots, line)
      unless fits?(obj)
        collect(roots, line, obj.size)
        return false unless fits?(obj)
      end
      place(obj)
      true
    end

    def copy(obj, record, copied, queue)
      return unless obj && copied.add?(obj)

      obj.address = @top
      @top += obj.size
      obj.moves += 1
      record.live.add(obj)
      record.moved.add(obj)
      queue << obj
    end

    def collect(roots, line, request)
      record = new_record(line, request, 'copy')
      @base = @half - @base
      @top = @base
      copied = Set.new
      queue = []
      record.work += roots.length
      roots.each { |root| copy(root, record, copied, queue) }
      index = 0
      while index < queue.length
        obj = queue[index]
        index += 1
        record.work += obj.size + obj.fields.length
        obj.fields.each { |child| copy(child, record, copied, queue) }
      end
      @objects.each { |obj| record.freed.add(obj) unless copied.include?(obj) }
      @objects = queue
      finish_record(record)
    end
  end
end

module GCSim
  class Generational < Copying
    attr_reader :remembered, :barriers, :remembers

    MARKING_KINDS = %w[major full].freeze
    TENURING_KINDS = %w[tenure full].freeze
    COLLECTION_STEPS = [%w[major minor], %w[full tenure]].freeze

    def initialize(size, young, age)
      super(size)
      @young = young
      @half = young / 2
      @promotion_age = age
      @remembered = Set.new
      @barriers = @remembers = 0
      @target = 0
    end

    def young?(obj) = obj.address < @young
    def old_blocks = free_blocks(@objects, @young, @size)
    def free_list = super() + old_blocks

    def write_barrier(target, value)
      return if young?(target)

      @barriers += 1
      @remembers += 1 if value && young?(value) && @remembered.add?(target)
    end

    def allocate(obj, roots, line)
      if fits?(obj)
        place(obj)
        return true
      end
      COLLECTION_STEPS.each do |marking_kind, copying_kind|
        kind = largest_free(old_blocks) < @top - @base ? marking_kind : copying_kind
        return false unless collect(kind, roots, line, obj.size)

        if fits?(obj)
          place(obj)
          return true
        end
      end
      false
    end

    def sweep_old(record)
      @objects = @objects.select do |obj|
        next true if young?(obj)

        record.work += 1
        unless obj.marked
          record.freed.add(obj)
          @remembered.delete(obj)
        end
        obj.marked
      end
    end

    def evacuate(obj, record, pending, queue)
      return true unless obj && pending.delete?(obj)

      obj.age += 1
      obj.moves += 1
      if TENURING_KINDS.include?(record.kind) || obj.age >= @promotion_age
        address = first_fit(old_blocks, obj.size)
        return false if address.nil?

        obj.address = address
        record.promoted.add(obj)
      else
        obj.address = @target
        @target += obj.size
      end
      record.moved.add(obj)
      record.live.add(obj) unless MARKING_KINDS.include?(record.kind)
      queue << obj
      true
    end

    def evacuate_fields(obj, record, pending, queue)
      obj.fields.all? { |child| evacuate(child, record, pending, queue) }
    end

    def collect(kind, roots, line, request)
      record = new_record(line, request, kind)
      if MARKING_KINDS.include?(kind)
        Marking.mark(record, roots, @objects)
        sweep_old(record)
      end
      pending = @objects.select { |obj| young?(obj) }.to_set
      destination = @half - @base
      @target = destination
      queue = []
      record.work += roots.length
      roots.each { |root| return false unless evacuate(root, record, pending, queue) }
      by_address(@remembered).each do |obj|
        record.work += 1 + obj.fields.length
        return false unless evacuate_fields(obj, record, pending, queue)
      end
      index = 0
      while index < queue.length
        obj = queue[index]
        index += 1
        record.work += obj.size + obj.fields.length
        return false unless evacuate_fields(obj, record, pending, queue)
      end
      @objects = @objects.reject do |obj|
        dead = pending.include?(obj)
        record.freed.add(obj) if dead
        dead
      end
      @base = destination
      @top = @target
      @remembered = @objects.select do |obj|
        !young?(obj) && obj.fields.any? { |child| child && young?(child) }
      end.to_set
      finish_record(record)
      true
    end
  end
end

module GCSim
  class HeapObject
    attr_reader :number, :size, :fields
    attr_accessor :address, :marked, :moves, :age, :count

    def initialize(number, pointers, data)
      @number = number
      @size = 1 + pointers + data
      @fields = Array.new(pointers)
      @address = @moves = @age = @count = 0
      @marked = false
    end
  end

  class Pair
    attr_reader :count, :words

    def initialize(objects = [])
      @count = @words = 0
      objects.each { |obj| add(obj) }
    end

    def add(obj)
      @count += 1
      @words += obj.size
      self
    end

    def merge(other)
      @count += other.count
      @words += other.words
      self
    end

    def to_s = "#{@count} #{@words}"
  end

  module HeapTools
    extend self

    SIZE_CLASSES = %w[1 2-3 4-7 8-15 16+].freeze
    SIZE_LIMITS = [1, 3, 7, 15].freeze

    def by_address(objects) = objects.sort_by(&:address)
    def total_free(blocks) = blocks.sum { |_, length| length }
    def largest_free(blocks) = blocks.map(&:last).max || 0
    def free_stats(blocks) = [total_free(blocks), largest_free(blocks)]

    def free_blocks(objects, first, limit)
      blocks = []
      position = first
      by_address(objects).each do |obj|
        next unless obj.address >= first && obj.address < limit

        blocks << [position, obj.address - position] if obj.address > position
        position = obj.address + obj.size
      end
      blocks << [position, limit - position] if position < limit
      blocks
    end

    def first_fit(blocks, size)
      blocks.find { |_, length| length >= size }&.first
    end

    def dec2(numerator, denominator)
      rounded = (200 * numerator + denominator) / (2 * denominator)
      format('%d.%02d', rounded / 100, rounded % 100)
    end

    def pct(part, whole) = whole.zero? ? '-' : dec2(100 * part, whole)

    def class_table(values)
      counts = Array.new(SIZE_CLASSES.length, 0)
      values.each do |value|
        index = SIZE_LIMITS.index { |limit| value <= limit } || SIZE_LIMITS.length
        counts[index] += 1
      end
      SIZE_CLASSES.zip(counts).map { |label, count| "#{label}:#{count}" }.join(' ')
    end

    def heap_map(size, objects, reachable, inactive)
      cells = Array.new(size, '.')
      first, limit = inactive
      (first...limit).each { |address| cells[address] = '-' }
      objects.each do |obj|
        letter = (65 + (obj.number - 1) % 26).chr
        header, body = reachable.include?(obj.number) ? [letter, letter.downcase] : ['#', '=']
        cells[obj.address] = header
        (obj.address + 1...obj.address + obj.size).each { |address| cells[address] = body }
      end
      cells.join
    end
  end

  class CollectionRecord
    include HeapTools
    attr_reader :number, :line, :request, :kind, :live, :freed, :moved, :promoted,
                :before, :after
    attr_accessor :stack, :work

    def initialize(number, line, request, kind, blocks)
      @number, @line, @request, @kind = number, line, request, kind
      @live, @freed, @moved, @promoted = Array.new(4) { Pair.new }
      @stack = @work = 0
      @before = free_stats(blocks)
      @after = [0, 0]
    end

    def finish(blocks)
      @after = free_stats(blocks)
    end
  end

  class HeapState
    include HeapTools
    attr_reader :size, :objects, :records

    def initialize(size)
      @size = size
      @objects = []
      @records = []
    end

    def free_list = free_blocks(@objects, 0, @size)
    def inactive_range = [0, 0]

    def new_record(line, request, kind)
      CollectionRecord.new(@records.length + 1, line, request, kind, free_list)
    end

    def finish_record(record)
      record.finish(free_list)
      @records << record
    end
  end
end
